{
  "autorId": "autor-001",
  "contexto": "Una institución evalúa la arquitectura de una aplicación distribuida.",
  "preguntaDirecta": "¿Cuál alternativa describe una comunicación síncrona entre microservicios?",
  "opciones": [
    {
      "texto": "Un servicio invoca gRPC y espera la respuesta del otro servicio.",
      "correcta": true
    },
    {
      "texto": "Un servicio publica un evento y continúa sin esperar al consumidor.",
      "correcta": false
    },
    {
      "texto": "Dos servicios escriben directamente en la misma base de datos.",
      "correcta": false
    },
    {
      "texto": "Un consumidor procesa un mensaje de una cola sin responder al productor.",
      "correcta": false
    },
    {
      "texto": "Un servicio almacena un evento en su Outbox local.",
      "correcta": false
    }
  ],
  "justificacion": "En una comunicación síncrona el emisor espera una respuesta; gRPC permite ese patrón.",
  "bibliografia": "Material del curso de Arquitectura de Microservicios.",
  "competencia": "Diseño de software",
  "tema": "Microservicios",
  "subtema": "Comunicación entre microservicios",
  "nivelDificultad": "MEDIO"
}

