{
  "autorId": "autor-002",
  "contexto": "Un equipo diseña la comunicación entre el servicio de Preguntas y el de Revisión para evitar pérdida de eventos.",
  "preguntaDirecta": "¿Cuál alternativa describe correctamente el patrón Outbox?",
  "opciones": [
    {
      "texto": "El servicio escribe el evento en una tabla propia dentro de la misma transacción que el cambio de estado.",
      "correcta": true
    },
    {
      "texto": "El servicio publica el evento directamente a RabbitMQ antes de confirmar la transacción de base de datos.",
      "correcta": false
    },
    {
      "texto": "El servicio consumidor escribe directamente en la base de datos del servicio productor.",
      "correcta": false
    },
    {
      "texto": "El servicio productor invoca gRPC de forma asíncrona para notificar el cambio.",
      "correcta": false
    },
    {
      "texto": "El servicio productor omite persistir el evento si RabbitMQ no está disponible.",
      "correcta": false
    }
  ],
  "justificacion": "El patrón Outbox garantiza atomicidad entre el cambio de estado y la publicación del evento.",
  "bibliografia": "Material del curso de Arquitectura de Microservicios.",
  "competencia": "Diseño de software",
  "tema": "Microservicios",
  "subtema": "Consistencia eventual",
  "nivelDificultad": "MEDIO"
}

